 "<div style=\"text-align:center\"><div style=\"font-size:54px;font-weight:800;color:#b45309;line-height:1.05;font-family:'Space Grotesk', sans-serif\">+10 GW</div><div style=\"font-size:21px;margin-top:.35em;line-height:1.25\">de potencia renovable nueva</div><div style=\"font-size:16px;color:#4c5175;margin-top:.5em;line-height:1.25\">2025: 8,8 GW solares y 1,2 GW eólicos</div></div>": "<div style=\"text-align:center\"><div style=\"font-size:54px;font-weight:800;color:#b45309;line-height:1.05;font-family:'Space Grotesk', sans-serif\">+10 GW</div><div style=\"font-size:21px;margin-top:.35em;line-height:1.25\">potentzia berriztagarri berri</div><div style=\"font-size:16px;color:#4c5175;margin-top:.5em;line-height:1.25\">2025: 8,8 GW eguzki-energiakoak eta 1,2 GW eolikoak</div></div>",
